WITH flattened_attrs AS (SELECT id, items, attributes, ARRAY_MAX(TRANSFORM(items, li -> li.price)) AS max_item_price, SIZE(items) AS num_items, COALESCE(ship_to.zip, 'UNKNOWN') AS zip_or_unknown, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text FROM carts) SELECT CASE WHEN num_items >= 3 THEN 'PREMIUM' ELSE 'STANDARD' END AS num_items_tier, CASE WHEN max_item_price >= 205 THEN 'PREMIUM' ELSE 'STANDARD' END AS max_item_price_tier, COUNT(DISTINCT id) AS distinct_ids, SUM(max_item_price) AS total_max_item_price, MAX(max_item_price) AS max_max_item_price, COUNT(*) AS event_count FROM flattened_attrs GROUP BY num_items_tier, max_item_price_tier HAVING SUM(max_item_price) >= 0 ORDER BY num_items_tier
